from ta_emss.utilities.structure_to_lowercase import convert_structure_to_lowercase


class EmssStructuralAttribute(list):
    def __init__(self, parent_object, name, *args):
        super(EmssStructuralAttribute, self).__init__(convert_structure_to_lowercase(*args))
        self.name = name
        self.parent_object = parent_object
        self.get_structural_attribute_type()

    def get_structural_attribute_type(self):
        if not self or isinstance(self[0], dict):
            return "list_of_dict"
        else:
            assert 0, "Structural attribute type not supported"

    def get_attribute_name(self):
        return self.name

    def get_parent_object(self):
        return self.parent_object

    def get_number_of_records(self):
        return self.__len__()

    @staticmethod
    def get_subattributes_dict_parsed_for_edit(attribute, subattributes_dict, index):
        assert isinstance(subattributes_dict, dict), "Second input parameter should be dictionary. " \
                                                     "Different form of structural attribute not supported"
        concat_dict = {}
        for subattribute, value in subattributes_dict.items():
            key = "%s.%s[%s]" % (str(attribute), str(subattribute), str(index))
            concat_dict[key] = value
        return concat_dict

    def _are_subattributes_and_values_matching(self, subattributes_dict, **kwargs):
        assert isinstance(subattributes_dict, dict), "Wrong input data"
        for subattribute, value in kwargs.items():
            if not self._is_subattribute_with_value_in_dict(subattribute, value, subattributes_dict):
                return False
        return True

    def _is_subattribute_with_value_in_dict(self, subattribute, value, subattributes_dict):
        return str(subattribute).lower() in subattributes_dict and subattributes_dict[str(subattribute).lower()] == str(value).lower()

    def get_indexes_of_matching_subattributes_records(self, **kwargs):
        indexes = []
        for index, subattirbutes_dict in enumerate(self):
            if self._are_subattributes_and_values_matching(subattirbutes_dict, **kwargs):
                indexes.append(index)
        return indexes
